"use client";

import {
  cloneElement,
  type ReactElement,
  type ReactNode,
  type RefObject,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import type { Align, Side } from "../interaction/floating";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { hasFinePointer } from "../utils/motion";
import { cx } from "../utils/cx";

export type TooltipProps = {
  /** The tip text. Keep it to a short label; interactive content belongs in a `Popover`. */
  content: ReactNode;
  side?: Side;
  align?: Align;
  /** Hover delay before showing, ms. Keyboard focus shows it immediately. */
  delay?: number;
  className?: string;
  /** The single element that triggers the tip. It must accept a ref, `aria-describedby` and pointer/focus handlers. */
  children: ReactElement<Record<string, unknown>>;
};

type Handler = ((e: never) => void) | undefined;

/**
 * A label for a control, shown on hover (fine pointers only) and keyboard focus, hidden on Escape or blur. It
 * describes the trigger (`aria-describedby`); it never replaces an accessible name.
 */
export function Tooltip({ content, side = "top", align = "center", delay = 400, className, children }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const id = useId();
  const anchor = useRef<HTMLElement>(null);
  const tip = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const hide = useCallback(() => {
    clearTimeout(timer.current);
    setOpen(false);
  }, []);
  const show = useCallback((wait: number) => {
    clearTimeout(timer.current);
    if (wait <= 0) setOpen(true);
    else timer.current = setTimeout(() => setOpen(true), wait);
  }, []);
  useEffect(() => () => clearTimeout(timer.current), []);
  const { present, state } = usePresence(open, 140);
  useFloating(present, anchor as RefObject<Element | null>, tip, { side, align, offset: 8 });
  useDismiss(open, anchor as RefObject<Element | null>, tip, hide);

  const own = children.props;
  const chain = (name: string, fn: () => void) => (e: never) => {
    (own[name] as Handler)?.(e);
    fn();
  };
  return (
    <>
      {cloneElement(children, {
        ref: anchor,
        "aria-describedby": open ? id : (own["aria-describedby"] as string | undefined),
        onPointerEnter: chain("onPointerEnter", () => hasFinePointer() && show(delay)),
        onPointerLeave: chain("onPointerLeave", hide),
        onFocus: (e: { currentTarget: Element }) => {
          (own.onFocus as Handler)?.(e as never);
          if (e.currentTarget.matches(":focus-visible")) show(0);
        },
        onBlur: chain("onBlur", hide),
      })}
      {present ? (
        <div
          ref={tip}
          data-state={state}
          inert={state === "closed" || undefined}
          id={id}
          popover="manual"
          role="tooltip"
          className={cx("hm-floating hm-tooltip", className)}
        >
          {content}
        </div>
      ) : null}
    </>
  );
}
